select o, k, v, estado from (
  select 0 as o, '0 funciones de redes (conjunto)' as k,
         (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) from pg_proc p where p.pronamespace = to_regnamespace('redes') or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%')) as v,
         case (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname)) from pg_proc p where p.pronamespace = to_regnamespace('redes') or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_redes\_%')) when '1ba192724c2fddcf321104700829f3cc' then 'PUBLICADA (21-nov)' else 'OTRA: deténgase y avise' end as estado
  union all
  select 1, '1 funciones de técnica (conjunto)', (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname, p.oid::regprocedure::text)) from pg_proc p where p.pronamespace = to_regnamespace('tecnica') or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_tec\_%')), 'debe ser 3e9b0121e2b8beb313fad05de9e50f15 (PUBLICADA)'
  union all
  select 2, '2 funciones de campo (conjunto, sin f_no_borrar_catalogo)', (select md5(string_agg(md5(pg_get_functiondef(p.oid)), '' order by p.pronamespace::regnamespace::text, p.proname, p.oid::regprocedure::text)) from pg_proc p where (p.pronamespace = 'campo'::regnamespace and p.proname <> 'f_no_borrar_catalogo') or (p.pronamespace = 'public'::regnamespace and p.proname like 'geoportal\_campo\_%')), 'antes debe ser cf40d2a279c385d17a6cc5da2aac3fa9; después, anótela'
  union all
  select 3, '3 ' || a.f || ' (se reemplaza)', md5(pg_get_functiondef(to_regprocedure(a.f))),
         case md5(pg_get_functiondef(to_regprocedure(a.f))) when a.m then 'LA PUBLICADA' when n.m then 'REEMPLAZADA (aplicado)' else 'OTRA: deténgase y avise' end
    from (values ('public.geoportal_campo_personal(text,jsonb,text)', 'f8a83b02da97e8f6a729767f57a394c4'), ('public.geoportal_campo_historial_personal(text,jsonb,text)', 'e82377f5de26a2dcc1a007403889ba48')) a(f, m) join (values ('public.geoportal_campo_personal(text,jsonb,text)', '7028ce4016505ed5fd8ae706db91464c'), ('public.geoportal_campo_historial_personal(text,jsonb,text)', '639b9652575bffbe6390aa527f3d36f8')) n(f, m) on n.f = a.f
  union all
  select 4, '4 ' || n.f || ' (nueva)', case when to_regprocedure(n.f) is not null then md5(pg_get_functiondef(to_regprocedure(n.f))) end,
