    from (values ('public.geoportal_campo_personal_fijar(text,text,text,jsonb,text)', 'fc362a2894e064767cfca039fa5ed299'), ('public.geoportal_campo_cuadrillas(text,jsonb,text)', '76b1eb22a370ab461f977ba38be9e994'), ('public.geoportal_campo_cuadrilla_cambiar(text,jsonb,text)', '30ed5a23163f13c822c7d2393132541d'), ('public.geoportal_campo_catalogos(text,text)', '5bec9cab11e11387073e5783fb23638a'), ('public.geoportal_campo_catalogo_cambiar(text,jsonb,text)', 'b230fe8ad5d1944fbaf1106f51b47f68'), ('public.geoportal_campo_personal_actividad(text,text,text)', '93ad0bd10c4222d4b1f24e0da0e43824'), ('campo.f_persona_comercial(text)', '99af03344249f7260357528096e92829'), ('campo.f_area_vigente(text)', '09ac12c5df5877b84fbce54e6d014470'), ('campo.f_cuadrilla_vigente(text)', 'f38549b2c3ad1edb8a8c26c6b57e3cb7'), ('campo.f_actividades_propias(text)', '0670bad6770dbb5191dc21dd560359f7'), ('campo.f_cuadrilla_actividades(bigint)', '826d0065c2a0c783d498cbc88e98d6cc'), ('campo.f_miembros_cuadrillas()', '07dac444b04ec2c0939c6180fec91343'), ('campo.f_actividades_persona(text)', '69bc9bd73d5797b826b3e504c1d92070'), ('campo.f_quien_puede(text)', '5a381a87f432b8d2a6c88ad98a13fe3c'), ('campo.f_codigo_desde_nombre(text)', '797333afba14f417857b033ff0d52f08'), ('campo.f_motivo_personal(text,boolean)', '4d7f94c08ca8e75bb724e21d9b93e272'), ('campo.f_no_borrar_catalogo()', '740c50291aa0bb31a38f64724d6b3fd9')) n(f, m)
  union all
  select 5, '5 ' || a.f || ' (no se toca)', md5(pg_get_functiondef(to_regprocedure(a.f))), case when md5(pg_get_functiondef(to_regprocedure(a.f))) = a.m then 'SIN CAMBIO' else 'OTRA: deténgase y avise' end
    from (values ('public.geoportal_campo_personal_cambiar(text,text,text,text,text,text,text)', 'c0302a7b45307215d8f780d8c78cd396'), ('campo.f_formularios_personal()', '283a63c1ee3fad9e5956a65f8a4644b6'), ('campo.f_formularios_asignados(text)', '9069510eaa7fb578281a0069124ac4d1'), ('campo.f_cargo_vigente(text)', '8f2df41fb828f89acdaedf0bc0f722c7')) a(f, m)
  union all
  select 6, '6 tablas nuevas (5)', null, case (select count(*) from pg_class where oid in (to_regclass('campo.areas_comercial'), to_regclass('campo.actividades'), to_regclass('campo.catalogo_eventos'), to_regclass('campo.cuadrillas'), to_regclass('campo.cuadrilla_eventos')))
         when 0 then 'NO EXISTEN (sin aplicar)' when 5 then 'EXISTEN (aplicado o conservadas de una reversa)' else 'A MEDIAS: deténgase y avise' end
  union all
  select 7, '7 INFO personas de Comercial · eventos de Personal · cuadrillas', null,
